package forth

import (
	"errors"
	"strconv"
	"strings"
)

// forth is a simple evaluator for a subset of the Forth language.
type forth struct {
	stack []int
	words map[string][]string // user-defined words, stored as token bodies
}

// builtin words, keyed by lower-case name
var builtin = map[string]func(*forth) error{
	"+":    add,
	"-":    sub,
	"*":    mul,
	"/":    div,
	"dup":  dup,
	"drop": drop,
	"swap": swap,
	"over": over,
}

// Forth evaluates the given lines of Forth source and returns the
// resulting stack, or an error if evaluation fails.
func Forth(input []string) ([]int, error) {
	f := &forth{
		stack: []int{},
		words: map[string][]string{},
	}
	for _, line := range input {
		tokens := strings.Fields(line)
		i := 0
		for i < len(tokens) {
			if tokens[i] == ":" {
				// word definition: : name body... ;
				if i+1 >= len(tokens) {
					return nil, errors.New("illegal operation")
				}
				name := strings.ToLower(tokens[i+1])
				if isNumber(name) {
					return nil, errors.New("illegal operation")
				}
				i += 2
				body := []string{}
				for i < len(tokens) && tokens[i] != ";" {
					body = append(body, strings.ToLower(tokens[i]))
					i++
				}
				if i >= len(tokens) {
					return nil, errors.New("illegal operation")
				}
				f.words[name] = body
				i++ // skip past ';'
				continue
			}
			if err := f.exec(tokens[i]); err != nil {
				return nil, err
			}
			i++
		}
	}
	return f.stack, nil
}

// isNumber reports whether tok is a (possibly negative) integer literal.
func isNumber(tok string) bool {
	_, err := strconv.Atoi(tok)
	return err == nil
}

// exec executes a single token.
func (f *forth) exec(tok string) error {
	if n, err := strconv.Atoi(tok); err == nil {
		f.stack = append(f.stack, n)
		return nil
	}
	if body, ok := f.words[tok]; ok {
		for _, t := range body {
			if err := f.exec(t); err != nil {
				return err
			}
		}
		return nil
	}
	if fn, ok := builtin[tok]; ok {
		return fn(f)
	}
	return errors.New("undefined operation")
}

// popOne pops the top of the stack.
func (f *forth) popOne() (int, error) {
	if len(f.stack) == 0 {
		return 0, errors.New("empty stack")
	}
	v := f.stack[len(f.stack)-1]
	f.stack = f.stack[:len(f.stack)-1]
	return v, nil
}

// popTwo pops the top two values, returning (top, second).
func (f *forth) popTwo() (int, int, error) {
	if len(f.stack) == 0 {
		return 0, 0, errors.New("empty stack")
	}
	if len(f.stack) == 1 {
		return 0, 0, errors.New("only one value on the stack")
	}
	top := f.stack[len(f.stack)-1]
	second := f.stack[len(f.stack)-2]
	f.stack = f.stack[:len(f.stack)-2]
	return top, second, nil
}

func add(f *forth) error {
	a, b, err := f.popTwo()
	if err != nil {
		return err
	}
	f.stack = append(f.stack, a+b)
	return nil
}

func sub(f *forth) error {
	a, b, err := f.popTwo()
	if err != nil {
		return err
	}
	f.stack = append(f.stack, b-a)
	return nil
}

func mul(f *forth) error {
	a, b, err := f.popTwo()
	if err != nil {
		return err
	}
	f.stack = append(f.stack, a*b)
	return nil
}

func div(f *forth) error {
	a, b, err := f.popTwo()
	if err != nil {
		return err
	}
	if b == 0 {
		return errors.New("divide by zero")
	}
	f.stack = append(f.stack, a/b)
	return nil
}

func dup(f *forth) error {
	if len(f.stack) == 0 {
		return errors.New("empty stack")
	}
	top := f.stack[len(f.stack)-1]
	f.stack = append(f.stack, top)
	return nil
}

func drop(f *forth) error {
	_, err := f.popOne()
	return err
}

func swap(f *forth) error {
	a, b, err := f.popTwo()
	if err != nil {
		return err
	}
	f.stack = append(f.stack, a, b)
	return nil
}

func over(f *forth) error {
	if len(f.stack) == 0 {
		return errors.New("empty stack")
	}
	if len(f.stack) == 1 {
		return errors.New("only one value on the stack")
	}
	second := f.stack[len(f.stack)-2]
	f.stack = append(f.stack, second)
	return nil
}

